rules:
- id: "vuln-gitlab-oauth-plugin-695ce63f"
  pattern: |
    HttpSession session = $REQUEST.getSession(false);
    if (session != null) {
        ...
    }
    $REQUEST.getSession(true);
  pattern-not: |
    HttpSession session = $REQUEST.getSession(false);
    if (session != null) {
        session.invalidate();
    }
    $REQUEST.getSession(true);
  languages: ["java"]
  message: "Potential session fixation vulnerability. The code does not invalidate the existing session before creating a new one, which can allow an attacker to hijack a user's session. To fix this, invalidate the session before creating a new one."
  severity: ERROR
  metadata:
    source-url: github.com/jenkinsci/gitlab-oauth-plugin/commit/695ce63fddb3567cf8d87339ddc1fa3b67ae2db8
    category: security
    cwe: CWE-384
    owasp: A7
    references: ["https://owasp.org/www-project-top-ten/2017/A7_2017-Cross-Site_Scripting_XSS", "https://cwe.mitre.org/data/definitions/384.html"]
    technology: java
